const E=Engine,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=localStorage.getItem('da-lang')||'zh',view='overview',tab='group',chartType='bar',page=0,search='',result=null,resultInfo=null,joinRows=null;
let state={rows:demoData(),name:'demo',steps:[],source:'demo'},past=[],future=[];
try{const saved=JSON.parse(localStorage.getItem('da-workspace'));if(saved?.rows?.length&&saved.rows.length<=50000)state=saved;}catch{}
const T=(z,e)=>lang==='zh'?z:e;
const labels={order_id:['订单编号','Order ID'],date:['日期','Date'],region:['区域','Region'],category:['品类','Category'],channel:['渠道','Channel'],quantity:['数量','Quantity'],unit_price:['单价','Unit price'],discount:['折扣率','Discount'],revenue:['销售额','Revenue'],cost:['成本','Cost'],rating:['评分','Rating'],profit:['利润','Profit'],period:['时间段','Period']};
