const ops={sum:['求和','Sum'],mean:['平均值','Mean'],count:['非空计数','Non-null count'],nunique:['唯一值数','Unique count'],median:['中位数','Median'],min:['最小值','Minimum'],max:['最大值','Maximum'],std:['样本标准差','Sample std']};
Object.assign(labels,{column:['字段','Column'],count:['非空计数','Count'],mean:['平均值','Mean'],std:['样本标准差','Sample std'],min:['最小值','Minimum'],q25:['25% 分位数','25th percentile'],median:['中位数','Median'],q75:['75% 分位数','75th percentile'],max:['最大值','Maximum'],sum:['总和','Sum']});
const L=c=>labels[c]?T(...labels[c]):state.source==='demo'&&words[c]?T(...words[c]):/_(sum|mean|count|nunique|median|min|max|std)$/.test(c)?c.replace(/^(.*)_(sum|mean|count|nunique|median|min|max|std)$/,(_,b,o)=>L(b)+' · '+T(...ops[o])):c;
const V=v=>E.missing(v)?T('缺失','Missing'):typeof v==='number'?fmt(v):state.source==='demo'&&words[v]?T(...words[v]):String(v);
