const colOptions=(cs=E.cols(state.rows),selected)=>cs.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(L(c))}</option>`).join('');
const opOptions=()=>Object.keys(ops).map(o=>`<option value="${o}">${T(...ops[o])}</option>`).join('');
