const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',data:'M3 4h18v16H3zM3 10h18M3 15h18M9 4v16M15 4v16',clean:'m6 19 12-12M13 5l6 6M4 16l4 4M3 3l1 2M21 17l-2 1',analyze:'M4 20V10h4v10M10 20V4h4v16M16 20v-8h4v8',visualize:'M3 18l6-8 5 4 7-10M3 3v18h18',history:'M4 6a9 9 0 1 1-1 10M4 2v5h5M12 7v6l4 2',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M9 9a3 3 0 1 1 4 3v3M12 18h.01',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',undo:'M4 8h10a6 6 0 0 1 0 12M8 4 4 8l4 4',redo:'M20 8H10a6 6 0 0 0 0 12M16 4l4 4-4 4',arrow:'M4 12h16M14 6l6 6-6 6',spark:'m12 2 2 7 7 3-7 2-2 8-2-8-7-2 7-3z'};
