const titles={overview:['工作簿','Workbook'],data:['数据工作台','Data workspace'],clean:['清洗与转换','Clean & transform'],analyze:['统计分析','Analysis'],visualize:['可视化探索','Visual exploration'],history:['操作记录','Workflow'],help:['使用指南','Guide']};
