function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4300);}
function persist(){try{localStorage.setItem('da-workspace',JSON.stringify(state));}catch{toast(T('浏览器存储已满，本次数据仍保留在当前页面。','Browser storage is full. Data remains in this page.'));}}
function apply(rows,z,e,python){if(!rows.length){toast(T('结果没有数据行，已保留原表。请调整条件。','Result has no rows. Original data kept; adjust conditions.'));return;}past.push(E.clone(state));if(past.length>20)past.shift();future=[];state.rows=rows;state.steps.push({z,e,python,rows:rows.length,time:new Date().toISOString()});result=null;page=0;search='';persist();render();toast(T('已应用：','Applied: ')+T(z,e));}
function table(rows,limit=20){if(!rows.length)return `<div class="empty">${T('没有匹配的数据。','No matching data.')}</div>`;const cs=E.cols(rows);return `<div class="tablewrap"><table class="datatable"><thead><tr><th>#</th>${cs.map(c=>`<th title="${esc(c)}">${esc(L(c))}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map((r,i)=>`<tr><td class="mono">${i+1}</td>${cs.map(c=>`<td class="${E.missing(r[c])?'missing':''}" title="${esc(V(r[c]))}">${esc(V(r[c]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function stats(){const ps=E.profile(state.rows),cells=state.rows.length*ps.length,m=ps.reduce((s,p)=>s+p.missing,0),dups=state.rows.length-E.dedupe(state.rows).length;return {ps,cells,m,dups,complete:cells?(100*(cells-m)/cells):0};}
function render(){
 const nav=Object.keys(titles).map((k,i)=>`<button data-view="${k}" class="${view===k?'active':''}" aria-current="${view===k?'page':'false'}"><span class="tabpixel tab-${k}">${icon(k)}</span>${T(...titles[k])}</button>`).join('');
 const q=stats();
 $('#app').innerHTML=`<div class="desktop-shell"><header class="windowbar"><div class="appname"><span class="appicon">${icon('analyze')}</span><strong>${T('数析工坊','Data Atelier')}</strong><span class="appversion">/ PIXEL WORKBOOK</span></div><span class="systemstatus">● ${T('本地工作簿','Local workbook')}</span></header><div class="menubar"><div class="menuactions">${btn(T('打开数据…','Open data…'),'import')}${btn(T('导出 CSV','Export CSV'),'export')}${btn(T('使用指南','Guide'),'guide')}</div><div class="menuactions"><button class="btn icon" data-action="undo" title="${T('撤销','Undo')}" aria-label="${T('撤销','Undo')}" ${past.length?'':'disabled'}>${icon('undo')}</button><button class="btn icon" data-action="redo" title="${T('重做','Redo')}" aria-label="${T('重做','Redo')}" ${future.length?'':'disabled'}>${icon('redo')}</button><button class="lang" data-action="lang" aria-label="${T('切换为英文','Switch to Chinese')}">${lang==='zh'?'<b>中文</b> / EN':'中文 / <b>EN</b>'}</button></div></div><nav class="nav booktabs" aria-label="${T('主导航','Main navigation')}">${nav}</nav><main class="main"><div class="sheetline"><span class="filename">▤ ${esc(name())}</span><span>${fmt(state.rows.length,0)} ${T('行','rows')} · ${q.ps.length} ${T('列','columns')}</span><span>${T('缺失','Missing')} ${q.m} · ${T('重复','Duplicates')} ${q.dups}</span><span class="sheetlocal">${T('仅在当前浏览器保存','Saved only in this browser')}</span></div><div class="heading"><div><h1>${T(...titles[view])}</h1><p>${T(...subtitles[view])}</p></div><span class="viewstamp">${view.toUpperCase()} / 0${Object.keys(titles).indexOf(view)+1}</span></div><div id="content">${({overview:overview,data:dataView,clean:cleanView,analyze:analysisView,visualize:visualView,history:historyView,help:helpView})[view]()}</div><footer class="footnote"><span>${T('数据分析课程作品 · 合成教学数据','Data analysis coursework · Synthetic demo data')}</span><a href="https://pandas.pydata.org/docs/user_guide/" target="_blank" rel="noopener">pandas ${T('参考文档','reference')} ↗</a><span>${T('导入 · 整理 · 分析 · 导出','Import · Prepare · Analyze · Export')}</span></footer></main></div>`;
 if(view==='overview')drawOverview();if(view==='visualize')drawChart();if(view==='analyze'&&tab==='corr')drawCorrelation();if(result&&view==='analyze')showResult();bind();
 document.querySelectorAll('[data-source-sort]').forEach(b=>b.onclick=()=>{const c=b.dataset.sourceSort;apply(E.sort(state.rows,c),`按${L(c)}升序排序`,`Sort ${c} ascending`,`df = df.sort_values(${py(c)}, na_position="last")`);});
 window.dispatchEvent(new Event('atelier-language'));
}
function overview(){const q=stats(),cs=E.cols(state.rows);return `<section class="source-preview"><div class="sectionlabel"><h2>▤ ${T('当前数据表','Current table')}</h2><span>${T('前 6 行 · 点击列名升序排序','First 6 rows · Click a header to sort ascending')}</span>${btn(T('打开完整表格 →','Open full table →'),'explore')}</div><div class="tablewrap"><table class="datatable"><thead><tr><th>#</th>${cs.map(c=>`<th><button class="columnsort" data-source-sort="${esc(c)}" title="${esc(c)}">${esc(L(c))}<small>${E.type(state.rows,c)==='number'?'123':E.type(state.rows,c)==='date'?'date':'abc'} ↕</small></button></th>`).join('')}</tr></thead><tbody>${state.rows.slice(0,6).map((r,i)=>`<tr><td class="rownum">${i+1}</td>${cs.map(c=>`<td class="${E.missing(r[c])?'missing':''}">${esc(V(r[c]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="tablecaption"><span>df.shape = (${state.rows.length}, ${cs.length})</span><span>${T('完整率','Completeness')} ${fmt(q.complete,1)}% · ${numeric().length} ${T('个数值列','numeric columns')}</span></div></section><div class="notebookgrid"><section class="chartcell"><div class="sectionlabel"><span class="cellno">01</span><div><h2>${T('初步观察','First observation')}</h2><p id="overviewChartTitle"></p></div>${btn(T('更换图形 →','Change chart →'),'visualExplore')}</div><div id="overviewChart"></div><p id="overviewInsight" class="observationnote"></p></section><aside class="notepad"><div class="notepin"></div><h2>${T('数据备忘','Dataset notes')}</h2><p class="notequestion">${state.source==='demo'?T('哪些区域贡献了更多销售额？','Which regions contribute more revenue?'):T('先确认字段含义，再比较分组差异。','Check what each field means before comparing groups.')}</p><dl><div><dt>${T('来源','Source')}</dt><dd>${state.source==='demo'?T('合成零售示例','Synthetic retail demo'):T('用户导入','User import')}</dd></div><div><dt>${T('缺失单元格','Missing cells')}</dt><dd>${q.m}</dd></div><div><dt>${T('重复行','Duplicates')}</dt><dd>${q.dups}</dd></div><div><dt>${T('已应用操作','Applied steps')}</dt><dd>${state.steps.length}</dd></div></dl><p class="pencilnote">${q.m||q.dups?T('有缺失和重复，先整理，再下结论。','Missing values or duplicates need attention before conclusions.'):T('没有检测到缺失和重复，仍需核对业务含义。','No missing cells or exact duplicates detected. Still check the meaning.')}</p>${btn(T('去整理数据 →','Prepare the data →'),'clean')}<div class="noterule"></div><small>${T('提示：点像素猫可拍扁。它会一直停住，直到你点「唤醒」。','Tip: click the pixel cat to squash it. It stays still until you choose Wake.')}</small></aside></div><section class="workflowline"><span class="cellno">02</span><strong>${T('分析过程','Workflow')}</strong><div>${state.steps.length?state.steps.slice(-3).map((s,i)=>`<span>${i?' → ':''}${esc(T(s.z,s.e))}</span>`).join(''):T('还没有修改数据。可以先去重，再计算利润。','No transformations yet. Try deduplicating, then deriving profit.')}</div><button class="textbutton" data-view="history">${T('查看记录 ↗','View steps ↗')}</button></section>`;}
function svgChart(rows,x,y,type='bar',op='sum'){const W=700,H=300,left=60,right=20,top=20,bottom=48,pw=W-left-right,ph=H-top-bottom;let body='',summary='';
 if(type==='scatter'){const pairs=rows.map(r=>({x:E.num(r[x]),y:E.num(r[y])})).filter(p=>p.x!==null&&p.y!==null).slice(0,5000);if(!pairs.length)return {svg:emptyChart(),summary:T('没有有效的数值对。','No valid numeric pairs.')};let xs=pairs.map(p=>p.x),ys=pairs.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmin===xmax){xmin-=1;xmax+=1;}if(ymin===ymax){ymin-=1;ymax+=1;}const sx=v=>left+(v-xmin)/(xmax-xmin)*pw,sy=v=>top+ph-(v-ymin)/(ymax-ymin)*ph;for(let i=0;i<=4;i++){const yy=top+i*ph/4;body+=`<path class="axis" d="M${left} ${yy}h${pw}"/><text x="${left-8}" y="${yy+4}" text-anchor="end">${fmt(ymax-i*(ymax-ymin)/4,0)}</text><text x="${left+i*pw/4}" y="${H-19}" text-anchor="middle">${fmt(xmin+i*(xmax-xmin)/4,0)}</text>`;}body+=pairs.map(p=>`<circle cx="${sx(p.x)}" cy="${sy(p.y)}" r="3.5" fill="#8a6cad" opacity=".55"><title>${esc(L(x))}: ${fmt(p.x)} / ${esc(L(y))}: ${fmt(p.y)}</title></circle>`).join('');const c=E.corr(rows,x,y);summary=T(`Pearson r = ${fmt(c.r,3)}；有效配对 n = ${c.n}。相关性不代表因果。图最多显示 5,000 点。`,`Pearson r = ${fmt(c.r,3)}; valid pairs n = ${c.n}. Correlation does not imply causation. Chart shows up to 5,000 points.`);
 }else{let items;if(type==='hist'){const a=E.numbers(rows,y);if(!a.length)return {svg:emptyChart(),summary:T('没有可绘制的数值。','No numeric values to plot.')};const min=Math.min(...a),max=Math.max(...a),bins=Math.min(12,Math.max(4,Math.ceil(Math.sqrt(a.length)))),width=(max-min||1)/bins;items=Array.from({length:bins},(_,i)=>({label:fmt(min+i*width,0),value:0,tip:`${fmt(min+i*width)} — ${fmt(min+(i+1)*width)}`}));a.forEach(v=>items[Math.min(bins-1,Math.floor((v-min)/width))].value++);summary=T(`显示 ${a.length} 个非空数值；${bins} 个等宽分箱。缺失值不参与统计。`,`${a.length} non-null values; ${bins} equal-width bins. Missing values are excluded.`);
 }else{const grouped=E.group(rows,[x],y,op),key=`${y}_${op}`;items=grouped.map(r=>({label:V(r[x]),value:r[key],tip:V(r[x]),key:JSON.stringify(r[x])}));items=type==='line'?items.sort((a,b)=>String(a.label).localeCompare(String(b.label))):items.sort((a,b)=>(b.value??-Infinity)-(a.value??-Infinity));const count=items.length;items=items.filter(r=>r.value!==null).slice(0,24);summary=T(`${L(x)}分组，${L(y)}${T(...ops[op])}。显示 ${items.length}/${count} 组；悬停查看数值。`,`${L(x)} grouped by ${T(...ops[op])} of ${L(y)}. Showing ${items.length}/${count} groups; hover for values.`);}
 if(!items.length)return {svg:emptyChart(),summary:T('没有有效的分组结果。','No valid groups.')};const vals=items.map(p=>p.value),lo=Math.min(0,...vals),hi=Math.max(0,...vals)||1,span=hi-lo||1,sy=v=>top+ph-(v-lo)/span*ph,base=sy(0),step=pw/items.length;for(let i=0;i<=4;i++){const yy=top+i*ph/4;body+=`<path class="axis" d="M${left} ${yy}h${pw}"/><text x="${left-9}" y="${yy+4}" text-anchor="end">${fmt(hi-i*span/4,0)}</text>`;}
 if(type==='line'){const points=items.map((p,i)=>`${left+step*(i+.5)},${sy(p.value)}`);body+=`<path d="M${points.join('L')}" stroke="#567f9b" stroke-width="2.5" fill="none"/>`;items.forEach((p,i)=>body+=`<circle cx="${left+step*(i+.5)}" cy="${sy(p.value)}" r="4" fill="#d08863"><title>${esc(p.tip)}: ${fmt(p.value)}</title></circle>`);}else items.forEach((p,i)=>body+=`<rect x="${left+step*i+step*.14}" y="${Math.min(base,sy(p.value))}" width="${step*.72}" height="${Math.max(1,Math.abs(base-sy(p.value)))}" rx="2" fill="${type==='hist'?'#6588a5':categoryColor(p.key)}"><title>${esc(p.tip)}: ${fmt(p.value)}</title></rect>`);
 items.forEach((p,i)=>{if(items.length<=12||i%Math.ceil(items.length/10)===0)body+=`<text x="${left+step*(i+.5)}" y="${H-21}" text-anchor="middle">${esc(p.label.length>9?p.label.slice(0,8)+'…':p.label)}</text>`;});body+=`<path d="M${left} ${base}h${pw}" stroke="#aac0a2"/>`;
 }return {svg:`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(L(x))} / ${esc(L(y))} ${type}"><title>${esc(L(x))} / ${esc(L(y))}</title>${body}</svg>`,summary};}
const categoryPalette=['#8a6cad','#d08456','#5b87a4','#ad6378','#5a9487','#b19845','#7671b7'];
function categoryColor(key){const demo={East:'#d08456',South:'#5b87a4',West:'#8a6cad',North:'#5a9487'};if(key==='null')return '#b2aaa2';let h=0;for(const c of key)h=(h*31+c.charCodeAt(0))>>>0;return demo[JSON.parse(key)]||categoryPalette[h%categoryPalette.length];}
function emptyChart(){return `<div class="empty">${T('当前数据不足以绘制图形。请选择数值字段。','Insufficient data to draw a chart. Choose a numeric column.')}</div>`;}
function drawOverview(){const n=numeric(),c=categorical();if(!n.length){$('#overviewChart').innerHTML=emptyChart();$('#overviewInsight').textContent=T('可以先转换数值类型，或导入其他数据。','Convert a numeric field or import another dataset.');return;}const x=c.includes('region')?'region':c[0]||n[0],y=n.includes('revenue')?'revenue':n[0],chart=svgChart(state.rows,x,y,'bar','sum');$('#overviewChart').innerHTML=chart.svg;$('#overviewChartTitle').textContent=`${L(x)} × ${L(y)} · ${T('求和','Sum')}`;const groups=E.group(state.rows,[x],y,'sum'),key=y+'_sum',rank=[...groups].sort((a,b)=>b[key]-a[key]),total=groups.reduce((a,r)=>a+r[key],0);const share=total>0&&groups.every(r=>r[key]>=0)?T('，占总量 '+fmt(rank[0][key]/total*100,1)+'%',' ('+fmt(rank[0][key]/total*100,1)+'% of total)'):'';$('#overviewInsight').textContent=rank.length?T(V(rank[0][x])+'的'+L(y)+'总和最高，为 '+fmt(rank[0][key])+share+'。统计包含缺失分组，数值缺失不参与求和。',V(rank[0][x])+' has the highest total '+L(y)+': '+fmt(rank[0][key])+share+'. Includes a missing-key group; missing values are excluded from sums.'):chart.summary;}
function dataView(){let rows=state.rows;if(search)rows=rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(search.toLowerCase())));const pages=Math.max(1,Math.ceil(rows.length/15));page=Math.min(page,pages-1);return `<section class="panel"><div class="datahead"><div><strong>${esc(name())}</strong> <span class="pill">${rows.length} × ${E.cols(state.rows).length}</span></div><input class="search" id="search" aria-label="${T('搜索整张表','Search the table')}" placeholder="${T('搜索整张表…','Search the table…')}" value="${esc(search)}"></div>${table(rows.slice(page*15,(page+1)*15),15)}<div class="paging"><span>${T('第','Page')} ${page+1} / ${pages} · ${T('每页 15 行','15 rows per page')}</span><div class="actions">${btn('←','prev')}${btn('→','next')}</div></div></section><div class="grid equal"><section class="panel"><div class="panelhead"><div><h2>${T('条件筛选','Filter rows')}</h2><p>DataFrame.loc / boolean indexing</p></div></div><div class="formrow">${field('filterCol',T('字段','Column'),select('filterCol',colOptions()))}${field('filterOp',T('条件','Condition'),select('filterOp',[['eq','等于','Equals'],['ne','不等于','Not equal'],['contains','包含','Contains'],['gt','大于','Greater than'],['ge','大于等于','At least'],['lt','小于','Less than'],['le','小于等于','At most'],['missing','为空','Is missing'],['notmissing','非空','Not missing']].map(([v,z,e])=>`<option value="${v}">${T(z,e)}</option>`).join('')))}</div>${field('filterVal',T('比较值','Value'),'<input id="filterVal">')}${btn(T('预览筛选结果','Preview filter'),'filterPreview','primary')}<div id="filterPreview"></div></section><section class="panel"><div class="panelhead"><div><h2>${T('排序与字段选择','Sort & select columns')}</h2><p>sort_values / select columns</p></div></div><div class="formrow">${field('sortCol',T('排序字段','Sort column'),select('sortCol',colOptions()))}${field('sortOrder',T('顺序','Order'),select('sortOrder',`<option value="asc">${T('升序','Ascending')}</option><option value="desc">${T('降序','Descending')}</option>`))}</div>${btn(T('应用排序','Apply sort'),'sort','primary')}<div class="checkboxrow">${E.cols(state.rows).map(c=>`<label><input type="checkbox" name="keepcol" value="${esc(c)}" checked> ${esc(L(c))}</label>`).join('')}</div>${btn(T('保留选中字段','Keep selected columns'),'selectCols')}</section></div>`;}
function cleanView(){const q=stats();return `<section class="panel"><div class="panelhead"><div><h2>${T('数据质量报告','Data quality report')}</h2><p>${T('完整率按非缺失单元格计算；重复检测比较整行。','Completeness counts non-missing cells; duplicates compare entire rows.')}</p></div><span class="pill">${fmt(q.complete,1)}% ${T('完整','complete')}</span></div><div class="tablewrap"><table class="datatable"><thead><tr>${[T('字段','Column'),T('类型','Type'),T('缺失','Missing'),T('唯一值','Unique'),T('平均值','Mean'),T('最小值','Min'),T('最大值','Max')].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${q.ps.map(p=>`<tr><td>${esc(L(p.column))}</td><td>${p.type==='number'?T('数值','Number'):p.type==='date'?T('日期','Date'):T('文本','Text')}</td><td class="${p.missing?'warn':''}">${p.missing}</td><td>${p.unique}</td><td>${fmt(p.mean)}</td><td>${fmt(p.min)}</td><td>${fmt(p.max)}</td></tr>`).join('')}</tbody></table></div></section><div class="grid equal"><section class="panel"><div class="panelhead"><div><h2>${T('缺失值处理','Handle missing values')}</h2><p>fillna / dropna</p></div></div><div class="formrow">${field('fillCol',T('字段','Column'),select('fillCol',colOptions()))}${field('fillMethod',T('处理方式','Method'),select('fillMethod',[['mean','均值填充','Fill with mean'],['median','中位数填充','Fill with median'],['zero','零值填充','Fill with zero'],['constant','常量填充','Fill with constant'],['forward','前向填充','Forward fill'],['drop','删除该字段为空的行','Drop rows missing this field']].map(([v,z,e])=>`<option value="${v}">${T(z,e)}</option>`).join('')))}</div>${field('fillValue',T('常量（仅常量填充时使用）','Constant (used only for constant fill)'),'<input id="fillValue" placeholder="—">')}<div class="callout">${T('均值与中位数仅适合数值列。前向填充保留开头无法填充的缺失值。所有修改都能撤销。','Mean and median require numeric data. Forward fill preserves leading missing values. Every change can be undone.')}</div>${btn(T('应用处理','Apply treatment'),'fill','primary')}</section><section class="panel"><div class="panelhead"><div><h2>${T('重复与类型','Duplicates & types')}</h2><p>drop_duplicates / astype / to_datetime</p></div></div><div class="smallmetric"><span>${T('检测到整行重复','Exact duplicates detected')}</span><b>${q.dups}</b></div><div style="margin:14px 0">${btn(T('删除重复行','Remove duplicates'),'dedupe','primary')}</div><div class="formrow">${field('typeCol',T('字段','Column'),select('typeCol',colOptions()))}${field('typeTo',T('目标类型','Target type'),select('typeTo',`<option value="number">${T('数值','Number')}</option><option value="text">${T('文本','Text')}</option><option value="date">${T('日期（ISO）','Date (ISO)')}</option>`))}</div><p class="subtle">${T('无法转换的值会变成缺失值，请查看转换后的质量报告。','Values that cannot be converted become missing. Inspect the quality report afterward.')}</p>${btn(T('转换类型','Convert type'),'convert')}</section></div><div class="grid equal"><section class="panel"><div class="panelhead"><div><h2>${T('新增计算列','Create a derived column')}</h2><p>${T('用两列四则运算生成新字段','Arithmetic between two columns')}</p></div></div>${field('newName',T('新字段名','New column name'),'<input id="newName" value="profit">')}<div class="formrow three">${field('calcA',T('左侧字段','Left column'),select('calcA',colOptions(numeric(),'revenue')))}${field('calcOp',T('运算','Operation'),select('calcOp','<option>-</option><option>+</option><option>*</option><option>/</option>'))}${field('calcB',T('右侧字段','Right column'),select('calcB',colOptions(numeric(),'cost')))}</div><p class="subtle">${T('缺失输入或除以零会得到缺失值。','Missing inputs or division by zero produce missing values.')}</p>${btn(T('创建计算列','Create column'),'compute','primary')}</section><section class="panel"><div class="panelhead"><div><h2>${T('连接第二张表','Join another table')}</h2><p>merge · left / inner join</p></div></div>${btn(icon('upload')+T('导入关联表','Import lookup table'),'joinImport')}${joinRows?`<p class="subtle">${joinRows.length} ${T('行，字段：','rows, columns: ')}${E.cols(joinRows).map(esc).join(', ')}</p>`:`<p class="subtle">${T('示例可用 lookup.csv，以 region 为键，补充区域目标。','Use lookup.csv with region as the key to add regional targets.')}</p>`}<div class="formrow">${field('joinKey',T('共同键','Shared key'),select('joinKey',colOptions(joinRows?E.cols(state.rows).filter(c=>E.cols(joinRows).includes(c)):E.cols(state.rows),'region')))}${field('joinHow',T('连接方式','Join type'),select('joinHow',`<option value="left">${T('左连接：保留主表','Left: preserve main table')}</option><option value="inner">${T('内连接：仅匹配行','Inner: matching rows')}</option>`))}</div><p class="subtle">${T('重复键会展开为多行；同名字段自动添加 _right。','Repeated keys expand rows; overlapping columns receive _right.')}</p>${btn(T('应用连接','Apply join'),'merge','primary')}</section></div>`;}
function analysisView(){const names={group:['分组聚合','Group by'],pivot:['透视表','Pivot table'],describe:['描述统计','Describe'],time:['时间聚合','Time series'],corr:['相关性','Correlation']};return `<div class="tabstrip" role="tablist" aria-label="${T('分析类型','Analysis type')}">${Object.keys(names).map(k=>`<button role="tab" aria-selected="${tab===k}" class="${tab===k?'active':''}" data-tab="${k}">${T(...names[k])}</button>`).join('')}</div><section class="panel"><div class="panelhead"><div><h2>${T(...names[tab])}</h2><p>${({group:'groupby().agg()',pivot:'pivot_table()',describe:'describe() · ddof=1',time:'resample() / Grouper',corr:'corr(method="pearson")'})[tab]}</p></div><span class="mono">02 / ANALYZE</span></div>${tab==='group'?`<div class="formrow three">${field('groupKey',T('分组字段','Group column'),select('groupKey',colOptions(undefined,'region')))}${field('groupValue',T('数值字段','Value column'),select('groupValue',colOptions(undefined,'revenue')))}${field('groupOp',T('聚合函数','Aggregation'),select('groupOp',opOptions()))}</div>${btn(T('运行分组','Run group by'),'group','primary')}`:tab==='pivot'?`<div class="formrow">${field('pivotIndex',T('行字段','Rows'),select('pivotIndex',colOptions(undefined,'region')))}${field('pivotCol',T('列字段','Columns'),select('pivotCol',colOptions(undefined,'category')))}${field('pivotValue',T('值字段','Values'),select('pivotValue',colOptions(undefined,'revenue')))}${field('pivotOp',T('聚合函数','Aggregation'),select('pivotOp',opOptions()))}</div>${btn(T('生成透视表','Build pivot'),'pivot','primary')}`:tab==='describe'?`<p class="subtle">${T('统计仅包含数值列。标准差为样本标准差，分位数采用线性插值。缺失值不参与计算。','Statistics include numeric columns only. Standard deviation is sample std; quantiles use linear interpolation. Missing values are excluded.')}</p>${btn(T('计算描述统计','Calculate statistics'),'describe','primary')}`:tab==='time'?`<div class="formrow">${field('timeDate',T('日期字段','Date column'),select('timeDate',colOptions(undefined,'date')))}${field('timeValue',T('数值字段','Value column'),select('timeValue',colOptions(numeric(),'revenue')))}${field('timePeriod',T('时间粒度','Interval'),select('timePeriod',`<option value="month">${T('月','Month')}</option><option value="day">${T('日','Day')}</option><option value="year">${T('年','Year')}</option>`))}${field('timeOp',T('聚合函数','Aggregation'),select('timeOp',opOptions()))}</div><p class="subtle">${T('使用 ISO 日期的日历分组；无效或缺失日期会跳过并提示，不自动补齐空时间段。','Calendar groups use ISO dates. Invalid/missing dates are skipped and reported; empty intervals are not inserted.')}</p>${btn(T('聚合时间序列','Aggregate time series'),'time','primary')}`:`<div id="corrChart"></div><div class="callout">${T('Pearson 相关系数，范围 -1 到 1。按有效数值对计算；常量列和少于两个配对时显示 —。相关性不代表因果。','Pearson correlation ranges from -1 to 1. Uses valid numeric pairs; constant columns and fewer than two pairs show —. Correlation does not imply causation.')}</div>`}</section><div id="analysisResult"></div>`;}
function showResult(){if(!$('#analysisResult'))return;$('#analysisResult').innerHTML=`<section class="panel"><div class="resulthead"><h3>${T('分析结果','Analysis result')} <span class="pill">${result.length} ${T('行','rows')}</span></h3><div class="actions">${btn(T('导出结果 CSV','Export result CSV'),'resultExport')}${resultInfo?.apply?btn(T('作为当前数据','Use as current data'),'resultApply','primary'):''}</div></div>${resultInfo?.note?`<div class="callout">${esc(resultInfo.note)}</div>`:''}${table(result,100)}${result.length>100?`<p class="subtle">${T('预览前 100 行，导出包含全部结果。','Preview shows first 100 rows; export includes all results.')}</p>`:''}${resultInfo?.chart?`<div style="margin-top:20px">${svgChart(result,resultInfo.chart.x,resultInfo.chart.y,resultInfo.chart.type,'sum').svg}</div>`:''}</section>`;}
function visualView(){return `<div class="tabstrip">${[['bar','柱状图','Bar'],['line','折线图','Line'],['scatter','散点图','Scatter'],['hist','直方图','Histogram'],['heat','相关热力图','Heatmap']].map(([k,z,e])=>`<button data-chart="${k}" class="${chartType===k?'active':''}">${T(z,e)}</button>`).join('')}</div><section class="panel"><div class="formrow three">${field('chartX',T('横轴 / 分组','X axis / group'),select('chartX',colOptions(chartType==='scatter'?numeric():undefined,chartType==='scatter'?'quantity':chartType==='line'?'date':'region')))}${field('chartY',T('纵轴 / 数值','Y axis / value'),select('chartY',colOptions(numeric(),'revenue')))}${field('chartOp',T('聚合方式（柱状 / 折线）','Aggregation (bar / line)'),select('chartOp',opOptions()))}</div><div class="panelhead"><div><h2 id="chartTitle"></h2><p>${T('图形由当前数据实时生成 · 悬停查看数值','Charts use current data · Hover for values')}</p></div>${btn(chartType==='heat'?T('导出相关 CSV','Export correlation CSV'):T('下载 SVG','Download SVG'),'chartExport')}</div><div id="mainChart"></div><div id="chartSummary" class="insight"></div><div class="callout">${T('如何选图：类别比较用柱状，时间变化用折线，数值分布用直方，两变量关系用散点。折线按横轴标签排序；图形最多显示 24 个分组。','Choose a bar for categories, line for time, histogram for distribution and scatter for two variables. Lines sort by x labels; grouped charts show up to 24 groups.')}</div></section>`;}
function correlationHTML(){const cs=numeric().slice(0,10);if(!cs.length)return emptyChart();let html=`<div class="tablewrap"><table class="datatable"><thead><tr><th>Pearson r</th>${cs.map(c=>`<th>${esc(L(c))}</th>`).join('')}</tr></thead><tbody>`;for(const a of cs){html+=`<tr><th>${esc(L(a))}</th>`;for(const b of cs){const c=E.corr(state.rows,a,b),val=c.r;const color=val===null?'#f2f3ec':val>=0?`rgba(64,131,118,${.06+val*.73})`:`rgba(125,88,156,${.06-val*.73})`;html+=`<td style="background:${color};color:${Math.abs(val)>.65?'white':'#234337'};text-align:center" title="n = ${c.n}">${fmt(val,2)}</td>`;}html+='</tr>';}return html+'</tbody></table></div><div class="legend"><span>-1</span><div class="gradient"></div><span>+1</span></div><p class="subtle">'+T('最多显示前 10 个数值字段；悬停查看每格有效样本数。','Shows first 10 numeric fields; hover for the valid sample count.')+'</p>';}
function drawCorrelation(){$('#corrChart').innerHTML=correlationHTML();}
function drawChart(){const x=$('#chartX').value,y=$('#chartY').value,op=$('#chartOp').value;if(chartType==='heat'){$('#mainChart').innerHTML=correlationHTML();$('#chartSummary').textContent=T('按有效数值对计算 Pearson r。常量列显示 —。相关性不代表因果。','Pearson r uses valid numeric pairs. Constant columns show —. Correlation is not causation.');}else{const c=svgChart(state.rows,x,y,chartType,op);$('#mainChart').innerHTML=c.svg;$('#chartSummary').textContent=c.summary;}$('#chartTitle').textContent=chartType==='heat'?T('数值字段之间的关系','Relationships between numeric columns'):`${L(chartType==='hist'?y:x)} ${chartType==='hist'?T('数值分布','distribution'):'× '+L(y)}`;}
function pythonRecipe(){let code=`# Data Atelier — exported workflow\nimport pandas as pd\n\n# Choose your input file (CSV / TSV / JSON / XLSX).\n# Set the path and reader below to match your original data.\ndf = pd.read_csv("input.csv")\n`;for(const s of state.steps)code+='\n# '+s.e+'\n'+s.python+'\n';return code;}
function historyView(){return `<div class="grid equal"><section class="panel"><div class="panelhead"><div><h2>${T('分析操作记录','Applied workflow')}</h2><p>${T('最近 20 次修改可撤销；刷新后保留数据与步骤，但清空撤销栈。','Last 20 changes can be undone. Reload keeps data and steps, but clears undo history.')}</p></div><span class="pill">${state.steps.length} ${T('步','steps')}</span></div><div class="historyitem"><span class="num">0</span><div><strong>${T('载入数据','Load dataset')}</strong><small>${esc(name())}</small></div></div>${state.steps.map((s,i)=>`<div class="historyitem"><span class="num">${i+1}</span><div><strong>${esc(T(s.z,s.e))}</strong><small>${s.rows} ${T('行','rows')} · ${new Date(s.time).toLocaleTimeString(lang==='zh'?'zh-CN':'en-US',{hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')}${!state.steps.length?`<div class="callout">${T('修改数据后，步骤会出现在这里。','Applied changes appear here.')}</div>`:''}<div class="actions" style="margin-top:20px">${btn(T('恢复示例数据','Reset to demo'),'reset')}${btn(T('清除本地保存','Clear saved workspace'),'clearSaved')}</div></section><section class="panel"><div class="panelhead"><div><h2>${T('对应的 Python 步骤','Equivalent Python steps')}</h2><p>${T('供学习与复现；请按实际文件格式选择读取函数。','For learning and reproduction; choose the reader for your file format.')}</p></div></div><pre class="code">${esc(pythonRecipe())}</pre><div class="actions">${btn(T('下载 Python','Download Python'),'python','primary')}${btn(T('导出步骤 JSON','Export steps JSON'),'steps')}</div><div class="callout">${T('本网站由 JavaScript 在浏览器内运算，参考 pandas 的常见表格分析语义；不是完整 pandas 运行环境。Python 文件记录已应用的修改步骤。','This site computes locally in JavaScript, following common pandas table-analysis semantics. It is not a full pandas runtime. The Python file records applied transformations.')}</div></section></div>`;}
function helpView(){return `<section class="panel helpblock"><div class="panelhead"><div><h2>${T('十分钟，完成一次有依据的分析','A thoughtful analysis in ten minutes')}</h2><p>${T('功能参考 pandas；先提问，再选择工具。','Inspired by pandas; define your question before choosing a tool.')}</p></div><span class="pill">${T('课程作品指南','Coursework guide')}</span></div><h3>01 · ${T('提出一个可回答的问题','Ask an answerable question')}</h3><p>${T('例如：不同区域的销售额是否有差异？哪个品类带来最多利润？折扣与销售额之间存在什么关系？先确定指标、分组和时间范围。','For example: how does revenue differ by region? Which category generates the most profit? How are discounts and revenue related? Define your metric, groups and time range.')}</p><h3>02 · ${T('导入并核对数据','Import and inspect')}</h3><p>${T('支持 CSV、TSV、JSON 对象数组和 XLSX（第一张工作表）。CSV 第一行必须为唯一且非空的列名。支持引号、引号内换行和 UTF-8 BOM。单文件限制 10 MB，最多 50,000 行、100 列。数据保存在当前浏览器，不发送到服务器。','Supports CSV, TSV, JSON arrays of row objects and XLSX (first worksheet). CSV headers must be unique and non-empty. Quoted fields, embedded newlines and UTF-8 BOM are supported. Limit: 10 MB per file, 50,000 rows and 100 columns. Data stays in this browser, without server uploads.')}</p><h3>03 · ${T('清洗并记录理由','Clean with a reason')}</h3><p>${T('示例包含 243 行、11 列、3 个整行重复、16 个缺失单元格。先去重，再按含义处理缺失：均值填充适合某些连续变量，但不应无理由地填充销售额。用 revenue − cost 创建 profit，检查缺失输入对结果的影响。','The demo has 243 rows, 11 columns, 3 exact duplicates and 16 missing cells. Deduplicate first, then handle missing values based on meaning. Mean imputation can suit some continuous variables, but revenue should not be filled without a reason. Derive profit from revenue − cost and inspect the effect of missing inputs.')}</p><h3>04 · ${T('匹配分析方法','Match the analysis method')}</h3><ul><li>${T('分组聚合：按区域统计销售额总和、平均值、非空计数和标准差。','Group by: summarize revenue by region using sum, mean, non-null count or standard deviation.')}</li><li>${T('透视表：区域作为行、品类作为列、销售额作为值，比较组合差异。','Pivot: use region as rows, category as columns and revenue as values to compare segments.')}</li><li>${T('时间聚合：按日、月或年汇总 ISO 日期，跳过无效日期并显示数量。','Time series: aggregate ISO dates by day, month or year; skipped invalid dates are reported.')}</li><li>${T('描述统计：查看均值、中位数、分位数与样本标准差，不只看总量。','Describe: inspect mean, median, quantiles and sample standard deviation, not just totals.')}</li><li>${T('相关性：按有效配对计算 Pearson r，同时检查样本数与散点图。','Correlation: calculate Pearson r with valid pairs, while checking sample counts and the scatter plot.')}</li></ul><h3>05 · ${T('解释、导出与复现','Explain, export and reproduce')}</h3><p>${T('图形最多显示 24 个分组、5,000 个散点，完整结果可导出 CSV。热力图展示前 10 个数值列。数据 CSV 自动防止文本公式注入；支持 JSON、分析结果、图形 SVG 和 Python 步骤导出。所有图均由当前数据计算，不含硬编码的统计结果。','Charts show at most 24 groups or 5,000 scatter points; full results can be exported as CSV. Heatmaps show the first 10 numeric columns. CSV exports protect text against formula injection. Export data as CSV/JSON, results, SVG charts and Python steps. Every chart is calculated from current data, without hardcoded statistics.')}</p><div class="callout">${T('像素桌宠：点击拍扁并暂停；拖动可改变位置；点「唤醒」恢复飞行；可收起减少干扰。桌宠停在界面边缘活动，不影响表格操作。','Pixel pet: click to squash and pause; drag to reposition; Wake resumes flight; Hide reduces distractions. The pet stays near page edges to preserve workspace access.')}</div><h3>${T('参考与边界','References & scope')}</h3><p><a href="https://pandas.pydata.org/docs/user_guide/groupby.html" target="_blank" rel="noopener">pandas Group by</a> · <a href="https://pandas.pydata.org/docs/user_guide/missing_data.html" target="_blank" rel="noopener">Missing data</a> · <a href="https://pandas.pydata.org/docs/user_guide/merging.html" target="_blank" rel="noopener">Merge</a></p><p>${T('示例为固定随机种子生成的教学数据，不用于真实商业判断。表连接为左连接或内连接，日期聚合不补齐空时间段，计算列支持两列四则运算。网站覆盖常见 pandas 工作流，不宣称实现其全部 API。','The demo is synthetic teaching data generated with a fixed seed. Joins support left and inner modes; time groups do not insert empty intervals; derived columns support arithmetic between two columns. This site covers common pandas workflows, not every API.')}</p>${btn(T('下载示例 CSV','Download demo CSV'),'demoDownload')}${btn(T('下载关联表示例','Download lookup example'),'lookupDownload')}</section>`;}
const py=v=>JSON.stringify(v);
function download(text,filename,mime='text/plain;charset=utf-8'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;result=null;render();window.scrollTo(0,0);});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;result=null;render();});document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{chartType=b.dataset.chart;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{action(b.dataset.action);}catch(err){toast(T('操作未应用：','Operation not applied: ')+errorText(err));}});
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 for(const id of ['chartX','chartY','chartOp'])if($('#'+id))$('#'+id).onchange=drawChart;
}
function errorText(err){const map={'No numeric values in selected column':['该列没有可用的数值。','No numeric values in selected column.'],'Use a new, non-empty column name':['请使用新的非空字段名。','Use a new, non-empty column name.'],'Unclosed quoted field':['CSV 引号未闭合。','Unclosed CSV quoted field.'],'Inconsistent column count':['CSV 每行列数不一致。','Inconsistent CSV column count.'],'Column names must be non-empty and unique':['列名必须非空且唯一。','Column names must be non-empty and unique.'],'Expected a non-empty array of row objects':['JSON 应为非空的行对象数组。','JSON must be a non-empty array of row objects.'],'Limit: 50,000 rows and 100 columns':['最多支持 50,000 行、100 列。','Limit: 50,000 rows and 100 columns.'],'A header and at least one data row are required':['需要列名行和至少一行数据。','A header and at least one data row are required.'],'Pivot allows at most 50 categories':['透视表列字段最多 50 个类别。','Pivot allows at most 50 categories.'],'Conflicting suffix column names':['连接后字段名冲突，请先重命名关联表字段。','Conflicting join suffixes; rename lookup columns first.'],'Join exceeds 50,000 rows':['连接结果超过 50,000 行。','Join exceeds 50,000 rows.']};return map[err.message]?T(...map[err.message]):err.message;}
function action(a){let c,m,v,rows;switch(a){
 case 'lang':lang=lang==='zh'?'en':'zh';localStorage.setItem('da-lang',lang);document.documentElement.lang=lang==='zh'?'zh-CN':'en';result=null;render();break;
 case 'import':openImport();break;
 case 'visualExplore':view='visualize';render();break;case 'explore':view='data';render();break;case 'guide':view='help';render();break;case 'clean':view='clean';render();break;
 case 'undo':if(past.length){future.push(E.clone(state));state=past.pop();result=null;persist();render();toast(T('已撤销','Undone'));}break;
 case 'redo':if(future.length){past.push(E.clone(state));state=future.pop();result=null;persist();render();toast(T('已重做','Redone'));}break;
 case 'export':download(E.csv(state.rows),'data-atelier.csv','text/csv;charset=utf-8');toast(T('CSV 已导出。可在导入窗口选择 JSON 导出。','CSV exported. JSON export is available in the import dialog.'));break;
 case 'prev':page=Math.max(0,page-1);render();break;case 'next':page++;render();break;
 case 'sort':c=$('#sortCol').value;v=$('#sortOrder').value==='desc';apply(E.sort(state.rows,c,v),`按${L(c)}${v?'降序':'升序'}排序`,`Sort ${c} ${v?'descending':'ascending'}`,`df = df.sort_values(${py(c)}, ascending=${v?'False':'True'}, na_position="last")`);break;
 case 'selectCols':c=[...document.querySelectorAll('input[name="keepcol"]:checked')].map(b=>b.value);if(!c.length){toast(T('至少保留一个字段。','Keep at least one column.'));return;}apply(state.rows.map(r=>Object.fromEntries(c.map(k=>[k,r[k]]))),`选择 ${c.length} 个字段`,`Select ${c.length} columns`,`df = df[${py(c)}].copy()`);break;
 case 'filterPreview':c=$('#filterCol').value;m=$('#filterOp').value;v=$('#filterVal').value;rows=E.filter(state.rows,c,m,v);const count=rows.length;$('#filterPreview').innerHTML=`<div class="callout">${T('匹配','Matched')} ${count} / ${state.rows.length} ${T('行','rows')}</div>${table(rows,5)}<div style="margin-top:12px">${btn(T('应用筛选','Apply filter'),'applyFilter','primary')}</div>`;$('#filterPreview [data-action]').onclick=()=>{let expr=m==='missing'?`df[${py(c)}].isna()`:m==='notmissing'?`df[${py(c)}].notna()`:m==='contains'?`df[${py(c)}].astype("string").str.contains(${py(v)}, case=False, regex=False, na=False)`:`df[${py(c)}] ${{eq:'==',ne:'!=',gt:'>',ge:'>=',lt:'<',le:'<='}[m]} ${E.type(state.rows,c)==='number'?Number(v):py(v)}`;apply(rows,`筛选${L(c)}`,`Filter ${c}`,`df = df.loc[${expr}].copy()`);};break;
 case 'fill':c=$('#fillCol').value;m=$('#fillMethod').value;v=$('#fillValue').value;if(m==='constant'&&v===''){toast(T('请输入非空常量。','Enter a non-empty constant.'));return;}if(m==='constant'&&E.type(state.rows,c)==='number'){v=E.num(v);if(v===null){toast(T('数值列需要数值常量。','Numeric columns require a numeric constant.'));return;}}rows=m==='drop'?state.rows.filter(r=>!E.missing(r[c])):E.fill(state.rows,c,m,v);apply(rows,`处理${L(c)}缺失值（${m}）`,`Handle missing in ${c} (${m})`,m==='drop'?`df = df.dropna(subset=[${py(c)}])`:`df[${py(c)}] = df[${py(c)}].${m==='forward'?'ffill()':`fillna(${m==='mean'||m==='median'?`df[${py(c)}].${m}()`:m==='zero'?'0':py(v)})`}`);break;
 case 'dedupe':apply(E.dedupe(state.rows),'删除整行重复','Remove exact duplicates','df = df.drop_duplicates()');break;
 case 'convert':c=$('#typeCol').value;m=$('#typeTo').value;apply(E.convert(state.rows,c,m),`转换${L(c)}为${m}`,`Convert ${c} to ${m}`,`df[${py(c)}] = ${m==='number'?`pd.to_numeric(df[${py(c)}], errors="coerce")`:m==='date'?`pd.to_datetime(df[${py(c)}], errors="coerce").dt.strftime("%Y-%m-%d")`:`df[${py(c)}].astype("string")`}`);break;
 case 'compute':c=$('#newName').value.trim();const ca=$('#calcA').value,cb=$('#calcB').value,co=$('#calcOp').value;apply(E.compute(state.rows,c,ca,co,cb),`创建计算列 ${c}`,`Create derived column ${c}`,`df[${py(c)}] = df[${py(ca)}] ${co} ${co==='/'?`df[${py(cb)}].replace(0, float("nan"))`:`df[${py(cb)}]`}`);break;
 case 'joinImport':$('#joinInput').click();break;
 case 'merge':if(!joinRows){toast(T('请先导入关联表。','Import a lookup table first.'));return;}c=$('#joinKey').value;m=$('#joinHow').value;if(!c)throw new Error(T('没有共同字段。','No shared column.'));apply(E.merge(state.rows,joinRows,c,m),`以 ${c} 为键${m==='left'?'左连接':'内连接'}`,`${m} join on ${c}`,`lookup = pd.read_csv("lookup.csv")\ndf = df.merge(lookup, on=${py(c)}, how=${py(m)}, suffixes=("", "_right"))`);break;
 case 'group':c=$('#groupKey').value;v=$('#groupValue').value;m=$('#groupOp').value;result=E.group(state.rows,[c],v,m);resultInfo={apply:true,z:`按${L(c)}分组（${m}）`,e:`Group by ${c} (${m})`,python:`df = df.groupby(${py(c)}, dropna=False, sort=False)[${py(v)}].agg(${py(m)}).reset_index(name=${py(v+'_'+m)})`,chart:{x:c,y:v+'_'+m,type:'bar'}};showResult();break;
 case 'pivot':c=$('#pivotIndex').value;v=$('#pivotCol').value;if(c===v){toast(T('行字段与列字段请选择不同字段。','Choose different row and column fields.'));return;}m=$('#pivotOp').value;const pv=$('#pivotValue').value;if(pv===c||pv===v){toast(T('值字段应与行、列字段不同。','Choose a value column distinct from rows and columns.'));return;}result=E.pivot(state.rows,c,v,pv,m);resultInfo={apply:true,z:'生成透视表',e:'Build pivot table',python:`df = df.pivot_table(index=${py(c)}, columns=${py(v)}, values=${py(pv)}, aggfunc=${py(m)}, dropna=False).reset_index()`};showResult();break;
 case 'describe':result=numeric().map(c=>({column:L(c),...E.describe(state.rows.map(r=>r[c]))}));resultInfo={apply:false,note:T('标准差 ddof = 1；分位数为线性插值；排除缺失值。','Standard deviation ddof = 1; linear-interpolated quantiles; missing values excluded.')};showResult();break;
 case 'time':c=$('#timeDate').value;v=$('#timeValue').value;m=$('#timePeriod').value;const op=$('#timeOp').value,rs=E.resample(state.rows,c,v,m,op);result=rs.rows;resultInfo={apply:true,z:`按${m}聚合`,e:`Aggregate by ${m}`,note:T(`已跳过 ${rs.skipped} 行无效或缺失日期。`,`Skipped ${rs.skipped} invalid or missing dates.`),python:`df[${py(c)}] = pd.to_datetime(df[${py(c)}], errors="coerce")\ndf = df.dropna(subset=[${py(c)}]).assign(period=lambda x: x[${py(c)}].dt.strftime(${py(m==='year'?'%Y':m==='month'?'%Y-%m':'%Y-%m-%d')})).groupby("period")[${py(v)}].agg(${py(op)}).reset_index(name=${py(v+'_'+op)})`,chart:{x:'period',y:v+'_'+op,type:'line'}};showResult();break;
 case 'resultExport':download(E.csv(result),'analysis-result.csv','text/csv;charset=utf-8');break;
 case 'resultApply':apply(result,resultInfo.z,resultInfo.e,resultInfo.python);break;
 case 'chartExport':if(chartType==='heat'){toast(T('热力图请导出对应相关系数 CSV。','Export the correlation CSV for the heatmap.'));const cs=numeric().slice(0,10);download(E.csv(cs.map(a=>({column:a,...Object.fromEntries(cs.map(b=>[b,E.corr(state.rows,a,b).r]))}))),'correlation.csv','text/csv;charset=utf-8');}else if($('#mainChart svg'))download($('#mainChart svg').outerHTML.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" ').replace('><title','><style>text{font:11px sans-serif;fill:#736675}.axis{stroke:#e1d9dd;stroke-width:1}</style><title'),'data-atelier-chart.svg','image/svg+xml');break;
 case 'python':download(pythonRecipe(),'data-atelier-workflow.py');break;case 'steps':download(JSON.stringify(state.steps,null,2),'data-atelier-steps.json','application/json');break;
 case 'reset':past.push(E.clone(state));future=[];state={rows:demoData(),name:'demo',steps:[],source:'demo'};result=null;page=0;search='';joinRows=null;persist();render();toast(T('已恢复示例，可撤销。','Demo restored; you can undo.'));break;
 case 'clearSaved':localStorage.removeItem('da-workspace');toast(T('已清除本地保存；当前页面数据仍可使用。之后的新操作会重新保存。','Saved workspace cleared. Current data remains; future changes save again.'));break;
 case 'demoDownload':download(E.csv(demoData()),'demo-retail.csv','text/csv;charset=utf-8');break;
 case 'lookupDownload':download('region,target,manager\nEast,120000,Team A\nSouth,100000,Team B\nWest,90000,Team C\nNorth,110000,Team D\n','lookup.csv','text/csv;charset=utf-8');break;
}}
function openImport(){const d=$('#importDialog');d.innerHTML=`<div class="dialoghead"><div><h2>${T('让数据进入工坊','Bring your data in')}</h2><p class="subtle">${T('CSV · TSV · JSON · XLSX / 第一张工作表','CSV · TSV · JSON · XLSX / first worksheet')}</p></div><button class="btn" id="closeImport" aria-label="${T('关闭','Close')}">×</button></div><button class="dropzone" id="chooseFile" style="width:100%"><strong>${T('选择文件，或将文件拖到这里','Choose a file or drop it here')}</strong><small>${T('最大 10 MB · 50,000 行 · 100 列','Up to 10 MB · 50,000 rows · 100 columns')}</small></button>${field('pasteData',T('也可以直接粘贴 CSV / TSV','Or paste CSV / TSV'),`<textarea id="pasteData" placeholder="region,revenue&#10;East,1200&#10;South,950"></textarea>`)}<div id="importError" role="alert"></div><div class="actions">${btn(T('载入粘贴数据','Load pasted data'),'paste','primary')}${btn(T('下载示例 CSV','Download demo CSV'),'demoDownload')}${btn(T('导出当前 JSON','Export current JSON'),'json')}</div><p class="subtle">${T('导入会替换当前表，可撤销。JSON 需要为对象数组。UTF-8 中文文件可直接读取。','Import replaces the current table and can be undone. JSON expects an array of objects. UTF-8 text files are supported.')}</p>`;d.showModal();$('#closeImport').onclick=()=>d.close();$('#chooseFile').onclick=()=>$('#fileInput').click();$('#chooseFile').ondragover=e=>{e.preventDefault();};$('#chooseFile').ondrop=async e=>{e.preventDefault();if(e.dataTransfer.files[0])await importFile(e.dataTransfer.files[0]);};d.querySelector('[data-action="paste"]').onclick=()=>{try{loadData(E.parseCSV($('#pasteData').value),T('粘贴数据','Pasted data'));}catch(err){importError(err);}};d.querySelector('[data-action="demoDownload"]').onclick=()=>action('demoDownload');d.querySelector('[data-action="json"]').onclick=()=>download(JSON.stringify(state.rows,null,2),'data-atelier.json','application/json');}
function importError(err){const el=$('#importError');if(el)el.innerHTML=`<div class="inlineerror">${esc(T('导入失败：','Import failed: ')+errorText(err))}</div>`;else toast(errorText(err));}
function loadData(rows,filename){past.push(E.clone(state));if(past.length>20)past.shift();future=[];state={rows,name:filename,steps:[],source:'custom'};page=0;search='';result=null;joinRows=null;persist();$('#importDialog').close();render();toast(T('已载入 ','Loaded ')+rows.length+T(' 行数据。',' rows.'));}
async function readFile(file){if(file.size>10*1024*1024)throw new Error(T('文件超过 10 MB。','File exceeds 10 MB.'));const ext=file.name.split('.').pop().toLowerCase();if(ext==='xlsx'){if(!window.XLSX)throw new Error(T('Excel 读取组件未加载，请改用 CSV。','Excel reader did not load; use CSV.'));const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:null,raw:true});return E.normalize(rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,v instanceof Date?v.toISOString().slice(0,10):v]))));}const text=await file.text();return ext==='json'?E.normalize(JSON.parse(text)):ext==='csv'||ext==='tsv'?E.parseCSV(text,ext==='tsv'?'\t':undefined):(()=>{throw new Error(T('请选择 CSV、TSV、JSON 或 XLSX。','Choose CSV, TSV, JSON or XLSX.'));})();}
async function importFile(file,join=false){try{const rows=await readFile(file);if(join){joinRows=rows;render();toast(T('关联表已载入。','Lookup table loaded.'));}else loadData(rows,file.name);}catch(err){importError(err);}}
$('#fileInput').onchange=async e=>{if(e.target.files[0])await importFile(e.target.files[0]);e.target.value='';};$('#joinInput').onchange=async e=>{if(e.target.files[0])await importFile(e.target.files[0],true);e.target.value='';};
document.documentElement.lang=lang==='zh'?'zh-CN':'en';render();
if(!sessionStorage.getItem('atelier-opened')){sessionStorage.setItem('atelier-opened','1');const intro=document.createElement('div');intro.className='intro';intro.setAttribute('aria-hidden','true');intro.innerHTML=`<div><small>PIXEL × DATA</small><strong>${T('数析工坊','DATA ATELIER')}</strong><div class="introline"></div><small>A LITTLE CLARITY</small></div>`;document.body.append(intro);setTimeout(()=>intro.classList.add('out'),850);setTimeout(()=>intro.remove(),1350);}
